    }    else if (value is NativeEmbedRequest) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    }    else if (value is NativeEmbedResult) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    }    else if (value is NativeProbeResult) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else {
